body {
    font-family: 'Google Inter', sans-serif;
    background-color: #121212;
    color: #fff;
}

header {
    background-color: #1a1a1a;
    padding: 1rem;
    text-align: center;
}

header nav ul {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: space-between;
}

header nav ul li {
    margin-right: 20px;
}

header nav a {
    color: #fff;
    text-decoration: none;
}

main {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 2rem;
}

section {
    background-color: #2a2a2a;
    padding: 1rem;
    margin-bottom: 20px;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
}

h2 {
    margin-top: 0;
}

#text-prompt-workspace {
    display: flex;
    flex-direction: column;
    align-items: center;
}

#model-selector {
    margin-bottom: 10px;
}

#temperature-slider {
    margin-bottom: 10px;
}

#prompt-input {
    width: 100%;
    height: 100px;
    padding: 10px;
    font-size: 16px;
    border: none;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
}

#generate-button {
    background-color: #4CAF50;
    color: #fff;
    padding: 10px 20px;
    border: none;
    border-radius: 10px;
    cursor: pointer;
}

#live-ai-output-console {
    display: flex;
    flex-direction: column;
    align-items: center;
}

#output-console {
    width: 100%;
    height: 200px;
    padding: 10px;
    font-size: 16px;
    border: none;
    border-radius: 10px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
    overflow-y: auto;
}

#media-assets-gallery {
    display: flex;
    flex-direction: column;
    align-items: center;
}

#gallery-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
}

#gallery-list li {
    margin: 10px;
}

#gallery-list img {
    width: 100px;
    height: 100px;
    object-fit: cover;
    border-radius: 10px;
}

#system-status-footer {
    display: flex;
    flex-direction: column;
    align-items: center;
}

