const modelSelector = document.getElementById('model-selector');
const temperatureSlider = document.getElementById('temperature-slider');
const promptInput = document.getElementById('prompt-input');
const generateButton = document.getElementById('generate-button');
const outputConsole = document.getElementById('output-console');
const apiLatencySpan = document.getElementById('api-latency');
const gpuMemoryUsageSpan = document.getElementById('gpu-memory-usage');
const tokenUsageGaugeSpan = document.getElementById('token-usage-gauge');

// Add event listener to generate button
generateButton.addEventListener('click', async () => {
    const prompt = promptInput.value;
    const model = modelSelector.value;
    const temperature = temperatureSlider.value;

    // Call API to generate text
    const response = await fetch('/api/generate', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            prompt,
            model,
            temperature
        })
    });

    // Get response data
    const data = await response.json();

    // Update output console
    outputConsole.innerText = data.output;

    // Update API latency
    apiLatencySpan.innerText = `${data.apiLatency}ms`;

    // Update GPU memory usage
    gpuMemoryUsageSpan.innerText = `${data.gpuMemoryUsage}%`;

    // Update token usage gauge
    tokenUsageGaugeSpan.innerText = `${data.tokenUsageGauge}%`;
});

